src/lib/tests/air-sin-ofrecer-nov25.test.contenido:
// Mensaje 181 (25-nov-2026) · Aceptar el bloqueo no da permiso de ofrecer.
// En la prueba del 180 (2.7), el vendedor aceptó el bloqueo y en el mismo turno dijo «le dejo diez
// cubetas de 15W40, ¿se las bajo de una vez?». Sacó 100 y el aviso nuevo le dijo «esto no te bajó la
// nota»: el 2.7 y el 2.7c eran los únicos guiones del mundo 2 sin pitch_prematuro. Emilio: «Sí, que se
// califique». Y en esa prueba el aviso también salió por una pregunta de su negocio dicha después de
// presentarse y del bloqueo, que es justo lo que pide el nodo: ya no.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { PROMPT_ALCANCE, moldesDesde, textoDelAlcance } from "../../../supabase/functions/_shared/alcance";

const leer = (p: string) => readFileSync(join(process.cwd(), p), "utf8");
const nodos: any[] = JSON.parse(leer("docs/kb/nodos_snapshot.json"));
const ps = (id: string) => nodos.find((n) => n.id === id).practice_script;
const pitch = (id: string) => ps(id).failure_criteria.find((f: any) => f.id === "pitch_prematuro");
const red = JSON.parse(leer("supabase/functions/_shared/eval_harness_v1.json"));
const caso = (id: string) => red.cases.find((c: any) => c.id === id);
const datos = leer("docs/kb/doctrina_176_datos.sql");
const guia = [...datos.matchAll(/^ {2}\(\$t\$([a-z_0-9]+)\$t\$, (\d+), \$t\$([\s\S]*?)\$t\$, \$t\$([\s\S]*?)\$t\$\)/gm)]
  .map((m) => ({ clave: m[1], orden: Number(m[2]), titulo: m[3], texto: m[4] }));

describe("todo el mundo 2 con práctica califica el pitch prematuro", () => {
  it("también el 2.7 y el 2.7c, con la misma regla y la misma severidad", () => {
    const conFallas = nodos.filter((n) => n.world_id === 2 && n.practice_script?.failure_criteria?.length);
    expect(conFallas.length).toBeGreaterThan(0);
    for (const n of conFallas) expect(pitch(n.id), n.id).toBeTruthy();
    for (const id of ["2.7", "2.7c"]) {
      expect(pitch(id)).toMatchObject({ regla_id: "opening.pitch_prematuro", severity: "critical" });
      expect(pitch(id).severity_override).toBeUndefined();
    }
    expect([ps("2.7").version, ps("2.7c").version]).toEqual(["2.1.0", "1.1.0"]);
  });
  it("dice que aceptar el bloqueo no da permiso de ofrecer, y lo que sí se vale", () => {
    for (const id of ["2.7", "2.7c"]) {
      const d = pitch(id).description;
      expect(d).toContain("aceptar el bloqueo no da permiso de ofrecer");
      expect(d).toContain("no con producto ni pidiendo el pedido");
      expect(d).toContain("Preguntarle cómo le va (la semana, el negocio, el movimiento) es sobre él y no es esta falla.");
      expect(d).toContain("Ya que se presentó y el cliente le contestó, aunque sea con el bloqueo, preguntar por su negocio es descubrimiento y no es esta falla.");
    }
    expect(pitch("2.7c").description).toContain("quedar de regresar con dos opciones de día («¿el jueves o el viernes?») no es ofrecer");
  });
  it("lo que ya pedía el nodo no cambia", () => {
    expect(ps("2.7").failure_criteria.map((f: any) => f.id)).toEqual(["discute_el_bloqueo", "se_disculpa_o_se_va", "pide_permiso_de_nuevo", "ignora_sin_aceptar", "pitch_prematuro"]);
    expect(ps("2.7c").failure_criteria.map((f: any) => f.id)).toEqual(["insiste_tras_dos", "discute_el_bloqueo", "se_va_al_primero", "pide_permiso_de_nuevo", "se_va_con_disculpa", "pitch_prematuro"]);
  });
});

describe("la red lo prueba en los dos sentidos (v3.49.0)", () => {
  it("ofrecer después del AIR es pitch prematuro", () => {
    expect(red.harness_version).toBe("v3.49.0");
    const g = caso("G126_ofrece_despues_del_air");
    expect(g.node_id).toBe("2.7");
    expect(g.expected.must_flag).toEqual(["pitch_prematuro"]);
    expect(g.transcript[2].text).toContain("le dejo diez cubetas de 15W40");
  });
  it("una pregunta de su negocio después de presentarse y del bloqueo no es falla ni aviso", () => {
    const g = caso("G127_air_y_pregunta_de_su_negocio");
    expect(g.expected.must_not_flag).toContain("pitch_prematuro");
    expect(g.expected.feedback_must_not_match).toEqual(["es del paso 3"]);
    expect(leer("docs/kb/eval_harness_v1.json")).toBe(leer("supabase/functions/_shared/eval_harness_v1.json"));
  });
});

describe("el aviso de alcance", () => {
  it("recibe también «En cualquier paso» y «Cuando el cliente…», no los factores", () => {
    const m = moldesDesde(guia, 2);
    expect(m).toContain("## En cualquier paso");
    expect(m).toContain("Cuando el cliente… · Bloqueos");
    expect(m).toContain("## Paso 2 · Historia breve");
    expect(m).not.toContain("## Paso 1 · Introducción");
    expect(m).not.toContain("Los factores de impulso");
  });
  it("lo que la guía dice que se hace en ese momento no es pasarse", () => {
    expect(PROMPT_ALCANCE).toContain("Lo que la guía dice que se hace en ese momento NO es pasarse.");
    expect(PROMPT_ALCANCE).toContain("preguntarle por su negocio es lo que sigue, no un paso posterior");
  });
  it("no da por bueno lo que cita: ahí aprendes cómo se hace", () => {
    expect(textoDelAlcance(5, "pedir el pedido")).toBe("Pedir el pedido es del paso 5, el cierre: lo vemos más adelante en el mapa, y ahí aprendes cómo se hace. Esto no te bajó la nota.");
  });
});

describe("el SQL", () => {
  const correr = leer("docs/kb/guiones_181_correr.sql");
  const regresar = leer("docs/kb/guiones_181_regresar_correr.sql");
  it("sin BEGIN/COMMIT, con guardas, y el regreso quita solo lo que agregó", () => {
    for (const s of [correr, regresar]) expect(s).not.toMatch(/^\s*(BEGIN|COMMIT)\s*;/m);
    expect(correr).toContain("ya tiene pitch_prematuro");
    expect(correr).toContain("no está en la versión 2.0.4");
    expect(correr).toContain("no está en la versión 1.0.5");
    expect(regresar).toContain("no termina en la falla que agregó el 181");
    expect(regresar).not.toMatch(/DROP|DELETE/);
  });
});

src/lib/tests/alcance-nov25.test.ts.contenido:
// Mensaje 180 (25-nov-2026) · Te pasaste del alcance.
// Si en una práctica del paso 1 al 5 el vendedor hace algo de un paso posterior que no es una falla
// del nodo, la pantalla le dice, tranquila: «Aquí solo practicamos «…». Pedir el pedido es del paso
// 5, el cierre: lo vemos más adelante en el mapa, y ahí aprendes cómo se hace. Esto no te bajó la nota.» Opción A de Emilio: sin
// bajar la nota y sin calificar eso extra. Además, «Lo que buscamos» se ve mientras se califica.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  hayAlcanceQueRevisar, armarEntradaAlcance, moldesDesde, loQuePideElNodo, alcanceDeRespuesta,
  citaDelVendedor, yaEsFalla, textoDelAlcance, PROMPT_ALCANCE, HERRAMIENTA_ALCANCE,
} from "../../../supabase/functions/_shared/alcance";
import { avisoDeAlcance } from "../alcance-practica";

const leer = (p: string) => readFileSync(join(process.cwd(), p), "utf8");
const datos = leer("docs/kb/doctrina_176_datos.sql");
const guia = [...datos.matchAll(/^ {2}\(\$t\$([a-z_0-9]+)\$t\$, (\d+), \$t\$([\s\S]*?)\$t\$, \$t\$([\s\S]*?)\$t\$\)/gm)]
  .map((m) => ({ clave: m[1], orden: Number(m[2]), titulo: m[3], texto: m[4] }));
const nodos: any[] = JSON.parse(leer("docs/kb/nodos_snapshot.json"));

const conversacion = [
  { role: "user", content: "Buenas tardes, soy Emilio, de Aceites y Lubricantes Dalfán. Ando visitando talleres de la zona." },
  { role: "assistant", content: "Ah, órale. ¿Y qué se le ofrece?" },
  { role: "user", content: "Quería ofrecerle nuestro producto. ¿Le dejo diez cubetas de una vez?" },
];
const fallaPitch = [{ error: "Ofreciste producto en la introducción.", cita: "Quería ofrecerle nuestro producto." }];
const respuesta = (input: Record<string, unknown>) => ({ content: [{ type: "tool_use", name: "alcance", input }] });

describe("en qué nodos se revisa", () => {
  it("del paso 1 al 5; ni el 6 (no hay paso después) ni el mundo 7 (la línea completa)", () => {
    expect([1, 2, 3, 4, 5].every((p) => hayAlcanceQueRevisar(p))).toBe(true);
    expect(hayAlcanceQueRevisar(6)).toBe(false);
    expect(hayAlcanceQueRevisar(null)).toBe(false);
    expect(hayAlcanceQueRevisar(0)).toBe(false);
  });
});

describe("lo que recibe el revisor", () => {
  it("el molde de su paso y de los posteriores, de la misma guía con que se escriben los ejemplos", () => {
    expect(guia).toHaveLength(11);
    const m = moldesDesde(guia, 2);
    expect(m).toContain("## Paso 2 · Historia breve");
    expect(m).toContain("## Paso 5 · Cierre");
    expect(m).not.toContain("## Paso 1 · Introducción");
    expect(m).not.toContain("Los factores de impulso");
  });
  it("lo que pide el nodo, lo ya calificado como falla y la conversación numerada como la lee el juez", () => {
    const g = nodos.find((n) => n.id === "2.1").practice_script;
    const e = JSON.parse(armarEntradaAlcance({ paso: 2, nodo: "La primera frase", pide: loQuePideElNodo(g), moldes: moldesDesde(guia, 2), fallas: fallaPitch, conversacion }));
    expect(e.paso_del_nodo).toBe(2);
    expect(e.nombre_del_paso).toBe("la historia breve");
    expect(e.lo_que_pide_este_nodo.length).toBeGreaterThan(0);
    expect(e.ya_calificado_como_falla[0].cita).toBe("Quería ofrecerle nuestro producto.");
    expect(e.conversacion[2]).toEqual({ turno: 3, quien: "vendedor", dijo: conversacion[2].content });
  });
  it("el revisor no califica ni juzga: solo dice de qué paso es, y no cuenta lo ya calificado", () => {
    expect(PROMPT_ALCANCE).toContain("tú no calificas nada");
    expect(PROMPT_ALCANCE).toContain("No cuentes lo que ya se calificó como falla");
    expect(PROMPT_ALCANCE).toContain("No juzgues si estuvo bien o mal");
    expect(PROMPT_ALCANCE).toContain("ni lo que el vendedor le dice a Closer o a la app fuera de la venta");
    expect(HERRAMIENTA_ALCANCE.input_schema.required).toEqual(["se_paso"]);
  });
});

describe("el código revisa lo que contesta", () => {
  const bien = { se_paso: true, paso: 5, que_hizo: "pedir el pedido", cita: "¿Le dejo diez cubetas de una vez?", turno: 3 };
  it("si cuadra, sale el aviso con su texto", () => {
    const a = alcanceDeRespuesta(respuesta(bien), 2, conversacion, fallaPitch);
    expect(a).toEqual({ paso: 5, que: "pedir el pedido", cita: "¿Le dejo diez cubetas de una vez?", turno: 3, texto: "Pedir el pedido es del paso 5, el cierre: lo vemos más adelante en el mapa, y ahí aprendes cómo se hace. Esto no te bajó la nota." });
  });
  it("no sale si dice que no se pasó", () => {
    expect(alcanceDeRespuesta(respuesta({ se_paso: false }), 2, conversacion, [])).toBeNull();
  });
  it("no sale si el paso no es posterior al del nodo", () => {
    expect(alcanceDeRespuesta(respuesta({ ...bien, paso: 2 }), 2, conversacion, [])).toBeNull();
    expect(alcanceDeRespuesta(respuesta({ ...bien, paso: 1 }), 2, conversacion, [])).toBeNull();
    expect(alcanceDeRespuesta(respuesta({ ...bien, paso: 7 }), 2, conversacion, [])).toBeNull();
  });
  it("no sale en el 6 ni en el 7", () => {
    expect(alcanceDeRespuesta(respuesta(bien), 6, conversacion, [])).toBeNull();
    expect(alcanceDeRespuesta(respuesta(bien), null as unknown as number, conversacion, [])).toBeNull();
  });
  it("no sale si la cita no es del vendedor o no está en ese turno", () => {
    expect(alcanceDeRespuesta(respuesta({ ...bien, cita: "¿Y qué se le ofrece?", turno: 2 }), 2, conversacion, [])).toBeNull();
    expect(alcanceDeRespuesta(respuesta({ ...bien, turno: 1 }), 2, conversacion, [])).toBeNull();
    expect(alcanceDeRespuesta(respuesta({ ...bien, cita: "Le hago un descuento del veinte por ciento" }), 2, conversacion, [])).toBeNull();
    expect(citaDelVendedor("le dejo diez cubetas", 3, conversacion)).toBe(true);
  });
  it("no sale si es lo que ya se calificó como falla: eso ya tiene su explicación", () => {
    const comoLaFalla = { ...bien, paso: 4, que_hizo: "hablar del producto", cita: "Quería ofrecerle nuestro producto." };
    expect(alcanceDeRespuesta(respuesta(comoLaFalla), 2, conversacion, fallaPitch)).toBeNull();
    expect(yaEsFalla("ofrecerle nuestro producto", fallaPitch)).toBe(true);
    expect(yaEsFalla("¿Le dejo diez cubetas de una vez?", fallaPitch)).toBe(false);
  });
  it("no sale si falta lo que hizo o la respuesta viene rota", () => {
    expect(alcanceDeRespuesta(respuesta({ ...bien, que_hizo: "" }), 2, conversacion, [])).toBeNull();
    expect(alcanceDeRespuesta({ content: [] }, 2, conversacion, [])).toBeNull();
    expect(alcanceDeRespuesta(null, 2, conversacion, [])).toBeNull();
  });
  it("nombra cada paso como en la línea recta", () => {
    expect(textoDelAlcance(3, "preguntar por su operación")).toBe("Preguntar por su operación es del paso 3, el descubrimiento: lo vemos más adelante en el mapa, y ahí aprendes cómo se hace. Esto no te bajó la nota.");
    expect(textoDelAlcance(4, "hablar del producto")).toContain("del paso 4, la presentación:");
  });
});

describe("en closer-voice", () => {
  const cv = leer("supabase/functions/closer-voice/index.ts");
  it("corre después del porqué y antes de las estrellas, como llamada aparte y sin tocar la nota", () => {
    const i = cv.indexOf("sin porqué (fail-open)");
    const j = cv.indexOf('}, "alcance", {');
    const k = cv.indexOf("// Estrellas a partir del score YA topado.");
    expect(i).toBeGreaterThan(0);
    expect(j).toBeGreaterThan(i);
    expect(k).toBeGreaterThan(j);
    const bloque = cv.slice(j - 2000, k);
    expect(bloque).not.toMatch(/evaluation\.score\s*=/);
    expect(bloque).not.toMatch(/flags_detected/);
    expect(bloque).toContain("sin aviso de alcance (fail-open)");
    expect(bloque).toContain("tool_choice: { type: \"tool\", name: HERRAMIENTA_ALCANCE.name }");
    expect(bloque).toContain("moldesDesde(guiaPartes, pasoAlcance)");
    expect(bloque).toContain("hayAlcanceQueRevisar(pasoAlcance) && moldesAlcance");
  });
});

describe("en la pantalla", () => {
  const ui = leer("src/routes/nodo.$nodeId.practica.tsx");
  it("el aviso lleva el nombre del nodo", () => {
    const ev = { alcance: { texto: textoDelAlcance(5, "pedir el pedido"), cita: "¿Le dejo diez cubetas?" } };
    expect(avisoDeAlcance(ev, "La primera frase")).toEqual({
      texto: "Aquí solo practicamos «La primera frase». Pedir el pedido es del paso 5, el cierre: lo vemos más adelante en el mapa, y ahí aprendes cómo se hace. Esto no te bajó la nota.",
      cita: "¿Le dejo diez cubetas?",
    });
    expect(avisoDeAlcance(ev, "")?.texto.startsWith("Aquí solo practicamos este paso.")).toBe(true);
    expect(avisoDeAlcance({}, "La primera frase")).toBeNull();
    expect(avisoDeAlcance(null, "x")).toBeNull();
  });
  it("va después de «Tu avance», con su cita", () => {
    const a = ui.indexOf(">Tu avance<");
    const b = ui.indexOf(">Fuera de esta práctica<");
    expect(a).toBeGreaterThan(0);
    expect(b).toBeGreaterThan(a);
    expect(ui).toContain("Lo que dijiste: «{alcance.cita}»");
    expect(ui).toContain('nodeName={infoMapa?.nombre_corto || nodeData?.name || ""}');
  });
  it("mientras califica, se lee «Lo que buscamos» de metas_practica", () => {
    expect(ui).toContain("metas_practica?select=lo_que_buscamos,como_sabes&node_id=eq.");
    const espera = ui.slice(ui.indexOf(">Revisando tu práctica<"));
    expect(espera.indexOf("{metaEspera.lo_que_buscamos}")).toBeGreaterThan(0);
    expect(espera.indexOf("{metaEspera.lo_que_buscamos}")).toBeLessThan(espera.indexOf("<ListaRevision"));
  });
});

src/lib/tests/balas-que-apuntan-nov18.te.contenido:
// Mensaje 166 (18-nov-2026) · La doctrina de las balas, de raíz.
// Emilio: ante una objeción, una o dos balas, a veces tres, que respondan a lo que
// dijo el cliente. «No está mal soltar 1 o 2 balas seguidas, incluso se pueden soltar
// 3 a veces». Lo que importa es cuidarlas para no quedarse sin ellas. Vaciar el
// cargador es soltar balas que no apuntan, soltar de jalón todo lo que trae, o
// gastarse tantas que en la siguiente objeción ya no tiene con qué. Cuatro o más en
// una respuesta es señal de alerta, no falla automática. Quedarse desarmado solo se
// ve donde hay una objeción después.
// Mensaje 167: «lo que encontraron» por sí solo no es la bala; si ahí nombra algo concreto suyo
// (producto, servicio o precio), sí lo es; un precio con su motivo es bala aunque ya se haya dicho;
// y los criterios no castigan el número.
// Primero el Cerebro; de ahí la regla, las tarjetas, los guiones y la red.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const leer = (p: string) => readFileSync(join(process.cwd(), p), "utf8");
const cerebro = leer("docs/kb/cerebro_snapshot.md");
const reglas: any[] = JSON.parse(leer("docs/kb/reglas.json"));
const nodos: any[] = JSON.parse(leer("docs/kb/nodos_snapshot.json"));
const cards: any[] = JSON.parse(leer("docs/kb/cards_snapshot.json"));
const harness = JSON.parse(leer("supabase/functions/_shared/eval_harness_v1.json"));
const regla = (id: string) => reglas.find((r) => r.id === id);
const ps = (id: string) => nodos.find((n) => n.id === id).practice_script;
const caso = (id: string) => harness.cases.find((c: any) => c.id === id);

describe("Primero el Cerebro", () => {
  it("el paso 4 del FFF dice una o dos, a veces tres, que apunten, y define vaciar el cargador", () => {
    expect(cerebro).toContain("4. **Re-impulsa con la bala o las balas que respondan a lo que te dijo** `CAMPO`, y cierras. Una o dos es lo normal; a veces tres.");
    expect(cerebro).toContain("Cada bala tiene que apuntar a algo que el cliente dijo: su objeción, su dolor, su situación.");
    expect(cerebro).toContain("Vaciar el cargador es soltar balas que no apuntan a nada de lo que dijo, soltar de jalón todo lo que traes, o gastarte tantas que, cuando llega la siguiente objeción, ya no tienes con qué subir el impulso.");
    expect(cerebro).not.toContain("Tres de golpe sería vaciar el cargador");
    expect(cerebro).not.toContain("una sola, y cierras");
  });
  it("dice qué es una bala y por qué les decimos balas", () => {
    expect(cerebro).toContain("**Las balas son TUYAS.** Son hechos positivos y concretos");
    expect(cerebro).toContain("**Por qué les decimos balas** `CAMPO`");
  });
  it("cómo se sueltan ante una objeción: una o dos, a veces tres", () => {
    expect(cerebro).toContain("ante una objeción se re-impulsa con una o dos —a veces tres— que respondan a lo que te dijo.");
  });
});

describe("La regla es prueba, y su cita está en el Cerebro", () => {
  const r = () => regla("objection.vacia_el_cargador");
  it("tres partes, y ninguna cuenta balas", () => {
    expect(r().resumen).toContain("LA PRUEBA");
    expect(r().resumen).toContain("(1) ¿esta bala apunta a algo que el cliente dijo");
    expect(r().resumen).toContain("(2) ¿El vendedor le suelta de jalón una lista de todo lo que trae");
    // Mensaje 168 (Emilio, 23-nov): quedarse sin balas se califica por lo que se ve en ese turno, no con esta regla.
    expect(r().resumen).not.toContain("(3)");
    expect(r().resumen).toContain("Quedarse sin balas en la siguiente objeción no se califica con esta regla");
    expect(r().resumen).toContain("Una, dos o tres balas que apuntan a lo que dijo el cliente no son falla.");
    expect(r().resumen).toContain("Cuatro o más en una sola respuesta es señal de alerta");
    expect(r().resumen).not.toMatch(/dos o m[aá]s balas/);
  });
  it("su cita está en el Cerebro", () => {
    expect(cerebro).toContain(r().cita_cerebro);
  });
  it("present.balas dice lo mismo", () => {
    expect(regla("present.balas").resumen).toContain("lo normal es una o dos, a veces tres, y más no es falla si todas apuntan a lo que dijo y le quedan para lo que venga");
  });
});

describe("Tarjetas y guiones dicen lo mismo que el Cerebro", () => {
  const MUNDO5 = ["5.7", "5.8", "5.9", "5.10", "5.12", "5.13", "5.14", "5.15"];
  const viejo = /(?<!MENOS )UNA BALA|UNA bala|una sola bala|Una sola\.|una sola, la que|dos o m[aá]s (balas|argumentos)|dos o mas balas/;
  it("ninguna tarjeta del mundo 5 pide una sola bala", () => {
    for (const c of cards.filter((c) => MUNDO5.includes(c.node_id))) expect(`${c.node_id}#${c.card_order} ${c.body}`).not.toMatch(viejo);
  });
  it("ningún guion del mundo 5 pide una sola bala ni cuenta el cargador desde dos", () => {
    for (const id of MUNDO5) {
      const s = ps(id);
      if (!s) continue;
      const { notes, ...sinNotas } = s; // las notas guardan la historia
      expect(`${id} ${JSON.stringify(sinNotas)}`).not.toMatch(viejo);
    }
  });
  it("la tarjeta 4.5 #1 dice por qué les decimos balas", () => {
    expect(cards.find((c) => c.node_id === "4.5" && c.card_order === 1).body).toContain("Por eso les decimos balas");
  });
  it("el cliente simulado no se abruma con una, dos o tres que apuntan, y siente el desarme donde hay segunda objeción", () => {
    expect(ps("5.8").phases.you_do.prompt).toContain("Una, dos o tres balas que le hablan a tu objeción NO te abruman");
    for (const id of ["5.12", "5.15"]) expect(ps(id).phases.you_do.prompt).toContain("en la segunda ya no tiene nada concreto que le hable a tu nueva duda");
    expect(ps("5.8").phases.you_do.prompt).not.toContain("en la segunda ya no tiene nada concreto");
  });
  it("las versiones subieron", () => {
    expect(ps("5.8").version).toBe("1.2.0");
    expect(ps("5.10").version).toBe("2.3.0");
    expect(ps("5.12").version).toBe("1.4.0");
    expect(ps("5.15").version).toBe("1.4.0");
  });
});

describe("«Lo que encontraron» (mensaje 167): por sí solo no es la bala; con algo concreto del vendedor, sí", () => {
  const absoluto = /encontr[a-z]+»?"?(?: de FFF| otros clientes)?,? (?:en FFF, )?no (?:es|cuenta como) (?:la )?bala/i;
  it("el Cerebro lo dice, con el precio con su motivo", () => {
    expect(cerebro).toContain("Pero si ahí nombras algo concreto tuyo —de tu producto, tu servicio o tu precio, como «con la entrega cada martes nunca más perdieron una venta»—, eso sí es una bala.");
    expect(cerebro).toContain("Un precio con su motivo —«el primer pedido se lo dejo en mil cincuenta»— también lo es, aunque ya lo hayas dicho.");
    expect(cerebro).not.toContain("«Lo que encontramos» no es la bala");
  });
  it("ninguna regla, tarjeta ni guion lo dice de forma absoluta", () => {
    for (const r of reglas) expect(`${r.id} ${r.resumen}`).not.toMatch(absoluto);
    for (const c of cards) expect(`${c.node_id}#${c.card_order} ${c.body}`).not.toMatch(absoluto);
    for (const n of nodos) {
      if (!n.practice_script) continue;
      const { notes, ...sinNotas } = n.practice_script;
      expect(`${n.id} ${JSON.stringify(sinNotas)}`).not.toMatch(absoluto);
    }
  });
  it("salta_la_bala: la prueba dice qué sí cuenta", () => {
    const r = regla("objection.cierra_sin_bala").resumen;
    expect(r).toContain("eso sí es bala");
    expect(r).toContain("Un precio con su motivo");
    expect(r).toContain("Una bala ya dicha, aunque la repita tal cual, sí cuenta.");
  });
});

describe("Los criterios no castigan el número (mensaje 167)", () => {
  it("el criterio de balas del 5.8 y del 5.12 no pone tope", () => {
    const b8 = ps("5.8").success_criteria.find((c: any) => c.id === "objections.bullet_theory").description;
    const b12 = ps("5.12").success_criteria.find((c: any) => c.id === "objections.bullet_theory").description;
    expect(b8).toContain("más no le resta si todas apuntan");
    expect(b12).toContain("más no le resta si todas apuntan)");
    expect(b12).not.toContain("cuida su munición");
    expect(b8).not.toMatch(/—una o dos, a veces tres—/);
  });
});

describe("Quedarse sin balas se califica por lo que se ve (mensaje 168)", () => {
  it("5.12 y 5.15 tienen salta_la_bala, y vaciar el cargador ya no habla de la segunda objeción", () => {
    for (const id of ["5.12", "5.15"]) {
      const fallas = ps(id).failure_criteria;
      const salta = fallas.find((f: any) => f.id === "salta_la_bala");
      expect(salta.regla_id).toBe("objection.cierra_sin_bala");
      expect(salta.severity).toBe("major");
      expect(salta.description).toContain("eso es bala_se_cae, no esta");
      expect(salta.description).toContain("la explicacion le dice que ahi se le fueron");
      expect(fallas.find((f: any) => f.id === "vacia_el_cargador").description).not.toContain("segunda");
    }
  });
  it("lo que se enseña no cambia: el Cerebro y el cliente simulado siguen hablando de cuidarlas", () => {
    expect(cerebro).toContain("o gastarte tantas que, cuando llega la siguiente objeción, ya no tienes con qué subir el impulso");
    for (const id of ["5.12", "5.15"]) expect(ps(id).phases.you_do.prompt).toContain("en la segunda ya no tiene nada concreto que le hable a tu nueva duda");
  });
});

describe("La red (v3.46.0 en adelante)", () => {
  it("dos y tres que apuntan no son falla; desarmado sí; cuatro que apuntan y le quedan, no", () => {
    expect(["v3.46.0", "v3.47.0", "v3.48.0", "v3.49.0"]).toContain(harness.harness_version);
    expect(caso("G119_dos_balas_que_apuntan").expected.must_not_flag).toContain("vacia_el_cargador");
    expect(caso("G120_tres_balas_que_apuntan").expected.must_not_flag).toContain("vacia_el_cargador");
    expect(caso("G121_se_queda_desarmado").expected.must_flag).toEqual(["salta_la_bala"]);
    expect(caso("G121_se_queda_desarmado").expected.must_not_flag).toContain("vacia_el_cargador");
    expect(caso("G122_cuatro_que_apuntan_y_le_quedan").expected.must_not_flag).toContain("vacia_el_cargador");
    expect(caso("G96_apila_balas").expected.must_flag).toContain("vacia_el_cargador");
    expect(caso("G120_tres_balas_que_apuntan").expected.niveles_esperados["objections.bullet_theory"]).toBe("cumple");
    expect(caso("G122_cuatro_que_apuntan_y_le_quedan").expected.niveles_esperados["objections.bullet_theory"]).toBe("cumple");
    expect(caso("G123_precio_con_su_motivo_es_bala").expected.must_not_flag).toContain("salta_la_bala");
    expect(caso("G98_responde_sin_discutir").expected.must_flag).toEqual(["salta_la_bala"]);
  });
  it("el desarme se prueba solo donde hay una segunda objeción", () => {
    for (const id of ["G121_se_queda_desarmado", "G122_cuatro_que_apuntan_y_le_quedan"]) {
      expect(caso(id).node_id).toBe("5.12");
      expect(caso(id).transcript.filter((t: any) => t.role === "assistant").length).toBeGreaterThanOrEqual(3);
    }
  });
  it("el FFF con dos balas de V2 sigue quedando igual", () => {
    const v2 = harness.cases.find((c: any) => c.id.startsWith("V2_"));
    expect(v2.vara_textos[0].debe).toBe("quedar_igual");
    expect(v2.vara_textos[1].debe).toBe("cambiar");
  });
});

